/* Bounded legend/list truncation (#765).
 *
 * A long ranked legend or list used to either run forever (bloating its panel far past its
 * neighbours) or hide behind an inner scrollbar (unreachable by Cmd-F, unreadable on print, and
 * the exact treatment the operator asked removed). Neither is acceptable. This shows a bounded
 * default and offers an honest, keyboard-reachable way to see the rest: "Show all (N)" /
 * "Show less". Rank order, values and every existing per-item listener are untouched -- items
 * are hidden with the `hidden` attribute, never removed or re-created, so a delegated listener
 * bound to the container (as every legend on this surface already is) keeps working exactly as
 * it did before.
 *
 * Nothing here fetches, stores, mutates filters, or knows what an item MEANS. It only toggles
 * which of a container's existing children are visible.
 *
 * mountBoundedList(container, { defaultCount, expandLabel, collapseLabel })
 *   container      the element whose children are the ranked items, already built and appended
 *                   in rank order by the caller (a <ul>'s <li>s, or bare rows in a <div>)
 *   defaultCount    how many children stay visible before expansion (default 5)
 *   expandLabel(n)  label for the collapsed-state toggle; n is the total item count
 *   collapseLabel   label for the expanded-state toggle
 *   returns { element, isExpanded(), setItems(), destroy() } -- element is the toggle button,
 *   or null when there was nothing to bound (item count already within defaultCount).
 */
export function mountBoundedList(container, {
  defaultCount = 5,
  expandLabel = (n) => `Show all (${n})`,
  collapseLabel = "Show less",
} = {}) {
  let items = Array.from(container.children);
  let expanded = false;
  let toggle = null;

  const apply = () => {
    items.forEach((item, i) => { item.hidden = !expanded && i >= defaultCount; });
    if (toggle) {
      toggle.textContent = expanded ? collapseLabel : expandLabel(items.length);
      toggle.setAttribute("aria-expanded", String(expanded));
    }
  };

  const ensureToggle = () => {
    if (toggle || items.length <= defaultCount) return;
    toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "bounded-list__toggle";
    toggle.setAttribute("aria-expanded", "false");
    toggle.addEventListener("click", () => { expanded = !expanded; apply(); });
    if (container.nextSibling) container.parentNode.insertBefore(toggle, container.nextSibling);
    else container.parentNode.appendChild(toggle);
  };

  const removeToggle = () => {
    if (!toggle) return;
    toggle.remove();
    toggle = null;
  };

  ensureToggle();
  apply();

  return {
    get element() { return toggle; },
    isExpanded: () => expanded,
    /* A re-render rebuilt the container's children (every panel on this surface does, on every
     * filter change) -- re-read them and re-apply the same expanded/collapsed state rather than
     * forcing a reader who opened "Show all" back to collapsed on their next click. */
    setItems() {
      items = Array.from(container.children);
      removeToggle();
      ensureToggle();
      apply();
    },
    destroy() {
      removeToggle();
      items.forEach((item) => { item.hidden = false; });
    },
  };
}
